sp_widget.client_script:
api.controller=(function() {
    $scope.visibleCount = 20; 

    // Wait for data to load
    $timeout(function() {
        console.log("Employee Data Loaded:", $scope.data.employees);

        if (!$scope.data.employees || $scope.data.employees.length === 0) {
            console.error("No employees found. Check the server script.");
        }
    }, 1000);

    $scope.getFilteredEmployees = function() {
        var searchText = ($scope.searchText || "").toLowerCase();
        console.log("Search Text:", searchText);

        if (!$scope.data.employees) {
            console.error("Employee data is missing in Client Script!");
            return [];
        }

        var filteredList = $scope.data.employees.filter(function(emp) {
            return (emp.employee_name && emp.employee_name.toLowerCase().includes(searchText)) ||
                   (emp.department && emp.department.toLowerCase().includes(searchText)) ||
                   (emp.manager && emp.manager.toLowerCase().includes(searchText));
        });

        console.log("Filtered Employees:", filteredList);
        return filteredList.slice(0, $scope.visibleCount);
    };

    $scope.loadMore = function() {
        if ($scope.visibleCount < $scope.data.employees.length) {
            $scope.visibleCount += 20;
            console.log("Increased visible count:", $scope.visibleCount);
        }
    };
})();

sp_widget.css:
/* Container Styling */
.employee-directory {
    max-width: 800px;
    margin: 20px auto;
    padding: 20px;
    background: #ffffff;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

/* Search Bar */
.search-bar {
    width: 100%;
    padding: 10px;
    margin-bottom: 15px;
    border: 1px solid #ccc;
    border-radius: 5px;
    font-size: 16px;
}

/* Employee Table */
.employee-table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
}

.employee-table th, .employee-table td {
    padding: 12px;
    border-bottom: 1px solid #ddd;
}

.employee-table th {
    background: #007bff;
    color: white;
    font-weight: bold;
}

.employee-table tr:hover {
    background: #f1f1f1;
}

/* Load More Button */
.load-more {
    display: block;
    width: 100%;
    padding: 10px;
    margin-top: 15px;
    background: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    transition: background 0.3s;
}

.load-more:hover {
    background: #0056b3;
}

sp_widget.script:
(function() {
    var employees = [];
    var gr = new GlideRecord('sys_user'); // Change to your correct table
    gr.addQuery('active', true);
    gr.query();

    while (gr.next()) {
        employees.push({
            employee_name: gr.getValue('employee_name') || "Unknown",
            department: gr.getDisplayValue('department') || "N/A",
            manager: gr.getDisplayValue('manager') || "N/A",
            start_date: gr.getValue('start_date') || "N/A"
        });
    }

    data.employees = employees;

    // Debugging Log for the Server-Side
    gs.info("Employee Data Sent: " + JSON.stringify(data.employees)); 
})();
